/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER school_posts_route_insert BEFORE INSERT ON school_posts FOR EACH ROW BEGIN IF NEW.file_url IS NOT NULL OR NEW.category IS NOT NULL OR NEW.uploaded_by IS NOT NULL THEN SET NEW.post_type = 'document'; ELSEIF NEW.starts_at IS NOT NULL OR NEW.ends_at IS NOT NULL OR NEW.location IS NOT NULL THEN SET NEW.post_type = 'event'; ELSEIF NEW.post_type IS NULL THEN SET NEW.post_type = 'post'; END IF; IF NEW.type IS NULL THEN SET NEW.type = NEW.post_type; END IF; END */;;
