--
-- Table structure for table `subjects`
--

DROP TABLE IF EXISTS `subjects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `subjects` (
  `id` varchar(50) NOT NULL,
  `subject_record_type` varchar(30) NOT NULL DEFAULT 'subject',
  `source_id` varchar(50) DEFAULT NULL,
  `subject_id` varchar(50) DEFAULT NULL,
  `grade_level` tinyint(3) unsigned DEFAULT NULL,
  `periods_per_week` tinyint(3) unsigned DEFAULT NULL,
  `code` varchar(50) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `credit` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `type` varchar(20) NOT NULL DEFAULT 'required',
  `assessment_type` varchar(30) NOT NULL DEFAULT 'GRADE_10',
  `status` varchar(20) NOT NULL DEFAULT 'active',
  `is_weighted` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `subjects_name_unique` (`name`),
  UNIQUE KEY `subjects_code_unique` (`code`),
  KEY `subjects_assessment_type_index` (`assessment_type`),
  KEY `subjects_subject_record_type_index` (`subject_record_type`),
  KEY `subjects_source_id_index` (`source_id`),
  KEY `subjects_subject_id_index` (`subject_id`),
  KEY `subjects_grade_level_index` (`grade_level`),
  CONSTRAINT `subjects_subject_id_final_fk` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
