  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `substitute_teachings_class_id_semester_id_status_index` (`class_id`,`semester_id`,`status`),
