  KEY `substitute_teachings_original_teacher_id_index` (`original_teacher_id`),
  KEY `substitute_teachings_substitute_teacher_id_index` (`substitute_teacher_id`),
  KEY `substitute_teachings_status_index` (`status`),
  KEY `substitute_teachings_created_by_index` (`created_by`),
  KEY `substitute_teachings_updated_by_index` (`updated_by`),
  CONSTRAINT `substitute_teachings_original_teacher_id_consolidated_fk` FOREIGN KEY (`original_teacher_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `substitute_teachings_substitute_teacher_id_consolidated_fk` FOREIGN KEY (`substitute_teacher_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
