INSERT INTO `system_settings` VALUES ('019f0873-11eb-7058-b8ed-b8f828de545e','home_page',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-27 02:39:46','2026-09-02 00:58:41','019f0873-11eb-7058-b8ed-b8f828de545e','banner',NULL,NULL,'Chào mừng đến với Trường Trung học Phổ thông Play Together','Hệ thống quản lý trường THPT giúp học sinh, giáo viên và phụ huynh dễ dàng theo dõi kết quả học tập, thời khóa biểu, thông báo và các hoạt động của nhà trường.','/storage/uploads/banners/banner_20260727_221135_coyxder0pb.png','{\"subtitle\":\"Môi trường học tập hiện đại - Kỷ cương - Sáng tạo - Phát triển toàn diện\"}'),('019f0873-120f-7157-9684-18cbedc7ab27','home_page',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-27 02:39:46','2026-07-27 15:02:03','019f0873-120f-7157-9684-18cbedc7ab27','about',NULL,NULL,'Giới thiệu nhà trường','Trường Trung học Phổ thông hướng đến xây dựng môi trường giáo dục hiện đại, lấy học sinh làm trung tâm, chú trọng phát triển kiến thức, kỹ năng và phẩm chất. Nhà trường không ngừng đổi mới phương pháp giảng dạy, ứng dụng công nghệ thông tin trong quản lý và học tập nhằm nâng cao chất lượng giáo dục.',NULL,NULL),('019f0873-1213-73a9-8b53-fb643b02f55d','home_page',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-27 02:39:46','2026-06-27 02:39:46','019f0873-1213-73a9-8b53-fb643b02f55d','contact',NULL,NULL,'Thông tin liên hệ','Nhà trường luôn sẵn sàng hỗ trợ học sinh, phụ huynh và giáo viên. Mọi thắc mắc vui lòng liên hệ qua điện thoại, email hoặc đến trực tiếp văn phòng trong giờ hành chính.',NULL,'{\"phone\":\"038 608 2608\",\"email\":\"hththam-cntt17@tdu.edu.vn\",\"address\":\"L\\u00ea B\\u00ecnh, qu\\u1eadn C\\u00e1i R\\u0103ng, tp C\\u1ea7n Th\\u01a1\"}'),('019f57b8-1ad3-728d-8956-d19cc8e22020','system','Quản lý trường THPT PTG','PTG','system/77vL8B6puXgcQ3Zq5386s8vjr8SO3nxR8LGy7hA4.png','Lê Bình, Cái Răng, Cần Thơ','038 608 2608','thpt@gmail.com','http://localhost/school-manager/public','Nguyễn Xúc Xích',NULL,'2026-07-12 12:05:11','2