/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER system_settings_route_insert BEFORE INSERT ON system_settings FOR EACH ROW BEGIN IF NEW.id IS NULL THEN SET NEW.id = UUID(); END IF; IF NEW.key IS NOT NULL AND NEW.value IS NOT NULL THEN SET NEW.setting_record_type = 'setting'; ELSEIF NEW.key IS NOT NULL THEN SET NEW.setting_record_type = 'home_page'; ELSEIF NEW.setting_record_type IS NULL THEN SET NEW.setting_record_type = 'system'; END IF; END */;;
