DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `id` varchar(50) NOT NULL,
  `username` varchar(100) NOT NULL,
  `full_name` varchar(255) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `phone` varchar(30) DEFAULT NULL,
  `password_hash` varchar(255) NOT NULL,
  `role` enum('admin','staff','teacher','homeroom','student','parent') NOT NULL DEFAULT 'student',
  `role_type` varchar(30) DEFAULT NULL,
  `source_profile_id` varchar(50) DEFAULT NULL,
  `student_code` varchar(50) DEFAULT NULL,
  `teacher_code` varchar(50) DEFAULT NULL,
  `parent_code` varchar(50) DEFAULT NULL,
  `teacher_id` varchar(50) DEFAULT NULL,
  `student_id` varchar(50) DEFAULT NULL,
  `parent_id` varchar(50) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `login_status` tinyint(1) NOT NULL DEFAULT 1,
  `is_super_admin` tinyint(1) NOT NULL DEFAULT 0,
  `force_change_password` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `gender` varchar(20) DEFAULT NULL,
  `dob` date DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `place_of_birth` varchar(255) DEFAULT NULL,
  `ethnicity` varchar(100) DEFAULT NULL,
  `religion` varchar(100) DEFAULT NULL,
  `parent_phone` varchar(50) DEFAULT NULL,
  `enrollment_date` date DEFAULT NULL,
  `admission_type` varchar(20) DEFAULT NULL,
  `previous_school` varchar(255) DEFAULT NULL,
  `transfer_grade_level` tinyint(3) unsigned DEFAULT NULL,
  `previous_class` varchar(50) DEFAULT NULL,
  `avatar` varchar(255) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `class_id` varchar(50) DEFAULT NULL,
  `school_year_id` varchar(50) DEFAULT NULL,
  `status` varchar(30) DEFAULT NULL,
  `joined_at` date DEFAULT NULL,
  `work_status` varchar(30) DEFAULT NULL,
  `qualification` varchar(255) DEFAULT NULL,
  `main_subject` varchar(255) DEFAULT NULL,
  `primary_subject_id` varchar(50) DEFAULT NULL,
  `department_id` varchar(50) DEFAULT NULL,
  `is_homeroom` tinyint(1) NOT NULL DEFAULT 0,
  `rbac_role_ids` longtext DEFAULT NULL,
  `permissions_map` longtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_username_unique` (`username`),
  UNIQUE KEY `users_student_code_unique` (`student_code`),
  UNIQUE KEY `users_teacher_code_unique` (`teacher_code`),
  UNIQUE KEY `users_parent_code_unique` (`parent_code`),
  KEY `users_teacher_fk` (`teacher_id`),
  KEY `users_student_fk` (`student_id`),
  KEY `users_parent_fk` (`parent_id`),
  KEY `users_role_type_index` (`role_type`),
  KEY `users_source_profile_id_index` (`source_profile_id`),
  KEY `users_class_id_index` (`class_id`),
  KEY `users_school_year_id_index` (`school_year_id`),
  KEY `users_primary_subject_id_index` (`primary_subject_id`),
  KEY `users_department_id_index` (`department_id`),
  CONSTRAINT `users_class_id_consolidated_fk` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_department_id_consolidated_fk` FOREIGN KEY (`department_id`) REFERENCES `teacher_departments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_parent_id_consolidated_fk` FOREIGN KEY (`parent_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_primary_subject_id_consolidated_fk` FOREIGN KEY (`primary_subject_id`) REFERENCES `subjects` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_school_year_id_consolidated_fk` FOREIGN KEY (`school_year_id`) REFERENCES `school_years` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_student_id_consolidated_fk` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_teacher_id_consolidated_fk` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

